class Solution {
public:
    int numRookCaptures(vector<vector<char>>& board) {
        int r = 0, c = 0;
        for (int i = 0; i < 8; ++i) {
            for (int j = 0; j < 8; ++j) {
                if (board[i][j] == 'R') {
                    r = i;
                    c = j;
                    break;
                }
            }
        }
        int res = 0;
        int dirs[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int d = 0; d < 4; ++d) {
            int nr = r + dirs[d][0];
            int nc = c + dirs[d][1];
            while (nr >= 0 && nr < 8 && nc >= 0 && nc < 8) {
                if (board[nr][nc] == 'B') break;
                if (board[nr][nc] == 'p') {
                    res++;
                    break;
                }
                nr += dirs[d][0];
                nc += dirs[d][1];
            }
        }
        return res;
    }
};

